CREATE EXTENSION IF NOT EXISTS pgcrypto;

CREATE TABLE categories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text NOT NULL UNIQUE, name_ar text NOT NULL, name_en text NOT NULL, image_url text, sort_order integer NOT NULL CHECK (sort_order > 0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE delivery_areas (id text PRIMARY KEY, name_ar text NOT NULL, name_en text NOT NULL, shipping_fee_minor bigint NOT NULL CHECK (shipping_fee_minor >= 0), is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX delivery_areas_active_idx ON delivery_areas(is_active);
CREATE TABLE products (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text NOT NULL UNIQUE, category_id uuid NOT NULL REFERENCES categories(id), name_ar text NOT NULL, name_en text NOT NULL, description_ar text NOT NULL DEFAULT '', description_en text NOT NULL DEFAULT '', unit_type text NOT NULL CHECK (unit_type IN ('crate','sack','carton','basket','bundle')), unit_label_ar text NOT NULL, unit_label_en text NOT NULL, weight_min_kg numeric(10,3) NOT NULL CHECK (weight_min_kg > 0), weight_max_kg numeric(10,3) NOT NULL CHECK (weight_max_kg >= weight_min_kg), price_minor bigint NOT NULL CHECK (price_minor >= 0), in_stock boolean NOT NULL DEFAULT true, max_per_order integer NOT NULL CHECK (max_per_order >= 1), cover_media_id uuid, price_updated_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX products_category_stock_idx ON products(category_id, in_stock);
CREATE INDEX products_name_search_idx ON products USING gin (to_tsvector('simple', name_ar || ' ' || name_en));
CREATE TABLE product_media (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid NOT NULL REFERENCES products(id) ON DELETE CASCADE, url text NOT NULL, media_type text NOT NULL CHECK (media_type IN ('image','video')), poster_url text, width integer CHECK (width > 0), height integer CHECK (height > 0), captured_at timestamptz, sort_order integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE products ADD CONSTRAINT products_cover_media_fk FOREIGN KEY (cover_media_id) REFERENCES product_media(id) ON DELETE SET NULL;
CREATE TABLE tags (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), text text NOT NULL UNIQUE);
CREATE TABLE product_tags (product_id uuid NOT NULL REFERENCES products(id) ON DELETE CASCADE, tag_id uuid NOT NULL REFERENCES tags(id) ON DELETE CASCADE, PRIMARY KEY(product_id,tag_id));
CREATE TABLE admin_users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL UNIQUE, name text NOT NULL, password_hash text NOT NULL, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE product_price_history (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid NOT NULL REFERENCES products(id), previous_price_minor bigint NOT NULL CHECK(previous_price_minor >= 0), new_price_minor bigint NOT NULL CHECK(new_price_minor >= 0), changed_by_admin_id uuid REFERENCES admin_users(id), changed_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE customers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), phone_e164 text NOT NULL UNIQUE CHECK (phone_e164 ~ '^\+20[0-9]{10}$'), password_hash text, name text NOT NULL, email text, age integer CHECK (age >= 0 AND age <= 120), city_area_id text REFERENCES delivery_areas(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX customers_email_unique ON customers(lower(email)) WHERE email IS NOT NULL;
CREATE TABLE customer_sessions (token_hash text PRIMARY KEY, customer_id uuid NOT NULL REFERENCES customers(id) ON DELETE CASCADE, expires_at timestamptz NOT NULL, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE otp_challenges (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), phone_e164 text NOT NULL, purpose text NOT NULL CHECK(purpose IN ('register','login')), code_hash text NOT NULL, attempts integer NOT NULL DEFAULT 0 CHECK(attempts >= 0), expires_at timestamptz NOT NULL, resend_after timestamptz NOT NULL, consumed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE registration_tokens (token_hash text PRIMARY KEY, phone_e164 text NOT NULL, expires_at timestamptz NOT NULL, consumed_at timestamptz);
CREATE TABLE auth_attempts (subject_key text NOT NULL, action text NOT NULL, window_start timestamptz NOT NULL, count integer NOT NULL DEFAULT 0 CHECK(count >= 0), blocked_until timestamptz, PRIMARY KEY(subject_key,action,window_start));
CREATE TABLE saved_addresses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_id uuid NOT NULL REFERENCES customers(id) ON DELETE CASCADE, area_id text NOT NULL REFERENCES delivery_areas(id), street text NOT NULL, building text NOT NULL, floor text, apartment text, landmark text, is_default boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX saved_addresses_one_default ON saved_addresses(customer_id) WHERE is_default;
CREATE TABLE orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), number text NOT NULL UNIQUE, customer_id uuid REFERENCES customers(id), tracking_token_hash text NOT NULL UNIQUE, status text NOT NULL DEFAULT 'pending_confirmation' CHECK(status IN ('pending_confirmation','confirmed','purchased','out_for_delivery','delivered','cancelled')), customer_name text NOT NULL, customer_phone_e164 text NOT NULL, area_id text REFERENCES delivery_areas(id), area_name_snapshot text NOT NULL, address_snapshot jsonb NOT NULL, subtotal_minor bigint NOT NULL CHECK(subtotal_minor >= 0), shipping_fee_minor bigint NOT NULL CHECK(shipping_fee_minor >= 0), total_minor bigint NOT NULL CHECK(total_minor = subtotal_minor + shipping_fee_minor), delivery_date date NOT NULL, window_start time NOT NULL, window_end time NOT NULL, payment_method text NOT NULL CHECK(payment_method = 'cash_on_delivery'), notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX orders_customer_created_idx ON orders(customer_id,created_at DESC);
CREATE TABLE order_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL REFERENCES orders(id) ON DELETE RESTRICT, product_id uuid NOT NULL REFERENCES products(id) ON DELETE RESTRICT, product_name_snapshot text NOT NULL, unit_label_snapshot text NOT NULL, quantity integer NOT NULL CHECK(quantity > 0), unit_price_minor bigint NOT NULL CHECK(unit_price_minor >= 0), line_total_minor bigint NOT NULL CHECK(line_total_minor = quantity * unit_price_minor));
CREATE TABLE order_status_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL REFERENCES orders(id) ON DELETE RESTRICT, from_status text, to_status text NOT NULL, actor_kind text NOT NULL, actor_id uuid, at timestamptz NOT NULL DEFAULT now(), note text);
CREATE TABLE idempotency_records (scope text NOT NULL, key text NOT NULL, request_fingerprint text NOT NULL, order_id uuid NOT NULL REFERENCES orders(id), expires_at timestamptz NOT NULL, PRIMARY KEY(scope,key));
CREATE TABLE contact_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, phone text, email text, message text NOT NULL, status text NOT NULL DEFAULT 'new' CHECK(status IN ('new','resolved')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE site_config (id boolean PRIMARY KEY DEFAULT true CHECK(id), value jsonb NOT NULL, version bigint NOT NULL DEFAULT 1, updated_by uuid REFERENCES admin_users(id), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE content_strings (locale text NOT NULL CHECK(locale IN ('ar','en')), key text NOT NULL, value text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(locale,key));
CREATE TABLE faqs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), question text NOT NULL, answer text NOT NULL, sort_order integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE static_pages (slug text PRIMARY KEY CHECK(slug IN ('about','terms','privacy')), title text NOT NULL, body_html text NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE announcements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), text_ar text NOT NULL, text_en text NOT NULL, sort_order integer NOT NULL DEFAULT 0, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE search_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), query text, selected_product_id uuid REFERENCES products(id) ON DELETE SET NULL, selected_category_id uuid REFERENCES categories(id) ON DELETE SET NULL, locale text CHECK(locale IN ('ar','en')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE admin_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE, description text NOT NULL DEFAULT '', system boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE admin_user_roles (admin_user_id uuid NOT NULL REFERENCES admin_users(id) ON DELETE CASCADE, role_id uuid NOT NULL REFERENCES admin_roles(id) ON DELETE RESTRICT, PRIMARY KEY(admin_user_id,role_id));
CREATE TABLE admin_role_permissions (role_id uuid NOT NULL REFERENCES admin_roles(id) ON DELETE CASCADE, permission_key text NOT NULL, PRIMARY KEY(role_id,permission_key));
CREATE TABLE admin_sessions (token_hash text PRIMARY KEY, admin_user_id uuid NOT NULL REFERENCES admin_users(id) ON DELETE CASCADE, expires_at timestamptz NOT NULL, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_entries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), admin_user_id uuid REFERENCES admin_users(id), action text NOT NULL, target_type text NOT NULL, target_id text, request_id text, change_summary jsonb, at timestamptz NOT NULL DEFAULT now());
CREATE TABLE outbox_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_type text NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), published_at timestamptz, retry_count integer NOT NULL DEFAULT 0 CHECK(retry_count >= 0));
